import type { Metadata } from "next";
import { siteConfig } from "@/config/site";

/** Link-preview image generated by /og. Titles are truncated so long text can never break the layout. */
export const ogImage = (title?: string, subtitle?: string) => {
  const q = new URLSearchParams();
  if (title) q.set("title", title.slice(0, 90));
  if (subtitle) q.set("sub", subtitle.slice(0, 120));
  const s = q.toString();
  return `/og${s ? `?${s}` : ""}`;
};

type Opts = { title: string; description: string; path: string; type?: "website" | "article"; publishedTime?: string; tags?: string[] };

/** One place that builds canonical, Open Graph and Twitter metadata so every page stays consistent. */
export function pageMetadata({ title, description, path, type = "website", publishedTime, tags }: Opts): Metadata {
  const image = ogImage(title, description);
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type, url: path, title, description, siteName: siteConfig.name, locale: "en_IN",
      images: [{ url: image, width: 1200, height: 630, alt: title }],
      ...(type === "article" ? { publishedTime, authors: [siteConfig.name], tags } : {}),
    },
    twitter: { card: "summary_large_image", title, description, images: [image] },
  };
}
